import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './components/Transaction.css';
import { FaWallet, FaMoneyBill, FaCheckCircle } from 'react-icons/fa';

function Transaction() {
    const [email] = useState(localStorage.getItem('email')); // Get email from local storage
    const [amount, setAmount] = useState('');
    const [transactionType, setTransactionType] = useState('deposit'); // Default to deposit
    const [message, setMessage] = useState('');
    const [balance, setBalance] = useState(null);

    useEffect(() => {
        const fetchBalance = async () => {
            try {
                const response = await axios.get(`http://localhost:8000/savings/${email}`);
                setBalance(response.data.balance);
            } catch (error) {
                console.error("Error fetching balance:", error);
            }
        };

        if (email) {
            fetchBalance();
        }
    }, [email]);

    const handleTransaction = async () => {
        try {
            const response = await axios.post('http://localhost:8000/transaction', {
                email,
                amount: parseFloat(amount), // Ensure amount is a number
                transactionType,
            });
            setMessage({ type: 'success', text: response.data.message });
            setBalance(response.data.balance); // Update displayed balance after transaction
            setAmount(''); // Clear input after successful transaction
        } catch (error) {
            setMessage({ type: 'error', text: 'Error processing transaction. Please try again.' });
            console.error("Error:", error);
        }
    };

    return (
        <div className="transaction-page">
            <div className="transaction-container">
                <div className="balance-section">
                    <FaWallet className="icon" />
                    <h3>Current Balance</h3>
                    <p className="balance-amount">₹ {balance?.toLocaleString() || '0.00'}</p>
                </div>

                <div className="transaction-form">
                    <h2>Make a Transaction</h2>

                    <div className="form-group">
                        <label htmlFor="amount">
                            <FaMoneyBill className="icon-inline" /> Enter Amount:
                        </label>
                        <input
                            type="number"
                            id="amount"
                            placeholder="Enter amount (₹)"
                            value={amount}
                            onChange={(e) => setAmount(e.target.value)}
                            required
                        />
                    </div>

                    <div className="form-group">
                        <label htmlFor="transactionType">
                            <FaMoneyBill className="icon-inline" /> Transaction Type:
                        </label>
                        <select
                            id="transactionType"
                            value={transactionType}
                            onChange={(e) => setTransactionType(e.target.value)}
                        >
                            <option value="deposit">Deposit</option>
                            <option value="withdraw">Withdraw</option>
                        </select>
                    </div>

                    <button className="transaction-button" onClick={handleTransaction}>
                        Submit Transaction
                    </button>

                    {message && (
                        <div
                            className={`message ${
                                message.type === 'success' ? 'success' : 'error'
                            }`}
                        >
                            <FaCheckCircle className="icon-inline" />
                            {message.text}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

export default Transaction;
